//! RFC 8785 (`jcs-1`) golden vectors shared with Python and TypeScript:
//! `tests/vectors/canonical_json_v2.json`, generated by
//! `tests/vectors/canonical_json_v2_vectors.py`.

use briefcase_core::integrity::{canonical_json_v2, parse_canonical_text, sha256_hex};
use serde_json::{Number, Value};

/// Decode the tagged input form. `Err` means "this implementation cannot
/// even hold the value", which counts as a rejection.
fn decode(value: &Value) -> Result<Value, String> {
    match value {
        Value::Array(items) => items
            .iter()
            .map(decode)
            .collect::<Result<_, _>>()
            .map(Value::Array),
        Value::Object(map) if map.len() == 1 && map.contains_key("$f64") => {
            let bits = u64::from_str_radix(map["$f64"].as_str().unwrap(), 16).unwrap();
            Number::from_f64(f64::from_bits(bits))
                .map(Value::Number)
                .ok_or_else(|| "non-finite".to_string())
        }
        Value::Object(map) if map.len() == 1 && map.contains_key("$bigint") => {
            let digits = map["$bigint"].as_str().unwrap();
            if let Ok(u) = digits.parse::<u64>() {
                Ok(Value::from(u))
            } else if let Ok(i) = digits.parse::<i64>() {
                Ok(Value::from(i))
            } else {
                Err(format!("{} does not fit i64/u64", digits))
            }
        }
        Value::Object(map) if map.len() == 1 && map.contains_key("$str") => {
            // serde_json refuses lone surrogates, which is the rejection.
            serde_json::from_str::<Value>(&format!("\"{}\"", map["$str"].as_str().unwrap()))
                .map_err(|e| e.to_string())
        }
        Value::Object(map) => map
            .iter()
            .map(|(k, v)| decode(v).map(|v| (k.clone(), v)))
            .collect::<Result<serde_json::Map<_, _>, _>>()
            .map(Value::Object),
        other => Ok(other.clone()),
    }
}

#[test]
fn rust_matches_the_shared_rfc8785_vectors() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/vectors/canonical_json_v2.json"
    );
    let doc: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert_eq!(doc["scheme"], "jcs-1");
    let vectors = doc["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 70);
    for vector in vectors {
        let name = vector["name"].as_str().unwrap();
        let decoded = decode(&vector["input"]);
        if vector.get("error").is_some() {
            let rejected = match decoded {
                Err(_) => true,
                Ok(value) => canonical_json_v2(&value).is_err(),
            };
            assert!(rejected, "{}: expected a rejection", name);
            continue;
        }
        let value = decoded.unwrap_or_else(|e| panic!("{}: {}", name, e));
        let text = canonical_json_v2(&value).unwrap_or_else(|e| panic!("{}: {}", name, e));
        assert_eq!(text, vector["canonical"].as_str().unwrap(), "{}", name);
        let hex: String = text
            .as_bytes()
            .iter()
            .map(|b| format!("{:02x}", b))
            .collect();
        assert_eq!(
            hex,
            vector["canonical_utf8_hex"].as_str().unwrap(),
            "{}",
            name
        );
        assert_eq!(
            sha256_hex(text.as_bytes()),
            vector["sha256"].as_str().unwrap(),
            "{}",
            name
        );
        // Canonical text read back with numbers as doubles re-encodes identically.
        let reparsed = parse_canonical_text(&text).unwrap();
        assert_eq!(
            canonical_json_v2(&reparsed).unwrap(),
            text,
            "{} round trip",
            name
        );
    }
}
